    title: "中文写法",
    summary: "中文标识符、标点穿透解析与调用规则",
    body: `本章说明 Pamela 对中文标识符、中文标点与中文内置名的支持范围与解析规则。

## 一、中文标识符

变量名、参数名与函数名可以使用中文。标识符以 Unicode 字母起始，其后可以是字母、数字与下划线，规则与英文名完全相同。

~~~pamela
分数 = 0
func 增加(数量) {
  分数 += 数量
}
增加(3)
~~~

## 二、标点的穿透解析

以下全角符号写在字符串之外时，按对应的半角符号解析，可以与半角符号混用：

- 中文逗号「，」按半角逗号解析。
- 中文括号「（」「）」按半角括号解析。
- 中文引号「“」「”」与「‘」「’」成对使用，作用与英文双引号、单引号相同。
- 中文分号「；」与中文冒号「：」分别按半角分号、冒号解析。

字符串内部的标点不受影响，「你好，世界」中的逗号原样显示。因此中文输入法状态下可以直接编写脚本，不必在中英文符号之间来回切换。

~~~pamela
小帕.缩放（2.0，3000）
对话框.说（“你好，世界”）
~~~

## 三、内置名对照

每一个内置名都有中文与英文两种写法，涵盖对象类型、全局函数、舞台与对象的方法、声音的方法，以及自由变换的八个点。完整清单连同签名与用途见「API 对照」一章，那里是对照表的唯一出处。

- 两种写法等价，可以混写：\`小帕.缩放（2.0，3000）\` 与 \`小帕.scale(2.0, 3000)\` 是同一次调用。
- 中文名在 \`.mpe\` 简写中同样可以直接调用。

## 四、参数名

参数名也有中文写法，与英文名等价：

~~~pamela
小帕 = 角色（“帕梅拉.png”，横 = -300，纵 = -500）
小帕.移动到（横 = 640，纵 = 200，时间 = 500）
小帕.说（台词 = “你好，我是帕梅拉！”）
~~~

- \`横\`、\`纵\` 按调用的参数表取值：在 \`移动到\` 中是舞台坐标，在 \`移动\` 中是偏移量，与两个方法的分工一致。创建对象时只有 \`x\`、\`y\`，因为新对象已位于原点。
- \`资源\`、\`路径\`、\`图片\`、\`文件\` 都指向第一个参数；\`缩放\`、\`缩放到\`、\`旋转\`、\`旋转到\`、\`透明度\`、\`模糊\`、\`亮度\`、\`对比度\`、\`饱和度\`、\`时间\`、\`台词\`、\`姓名\`、\`音量\` 等按各方法的参数表可用。
- 英文参数名同样可用，两种写法可以混写。

## 五、使用规则

- 中文名是回退规则：脚本自身绑定的名字优先。执行 \`说 = 1\` 之后，\`说\` 读到的是 1，而不是旁白。
- 报错按作者写下的原词报告，不做翻译：\`小帕 没有方法 跳\` 中的「跳」保持原样。
- 关键字仍为英文：\`if\`、\`else\`、\`while\`、\`for\`、\`func\`、\`return\`、\`choice\`、\`switch\`、\`include\`、\`jump\`、\`use\`、\`wait\`、\`cue\`。中文名只覆盖内置函数与方法。
- 旁白属于舞台，\`说\` 与 \`舞台.说\` 是同一次调用，两种写法均可。
- \`.mpe\` 中可以直接以空格分隔调用中文名：

~~~text
小帕 缩放 2.0 3000
小帕 说 你好，我是帕梅拉！
小帕 = 角色 帕梅拉.png 横=300 纵=-500
~~~

## 六、常见错误与排查

| 现象 | 原因 | 处理方式 |
| --- | --- | --- |
| 中文方法名报「没有方法」 | 使用了别名表中不存在的写法 | 按「API 对照」中的中文名书写 |
| 中文参数名报「没有这个参数」 | 该调用的参数表没有对应名称 | 按报错列出的名称修改，或改用英文参数名 |
| 台词中的标点被解析 | 台词未加引号，全角标点被当作代码 | 用引号包裹整句台词 |
| 关键字写成中文后报错 | 关键字只有英文写法 | 将 \`如果\`、\`当\` 等改为 \`if\`、\`while\` |
| 绑定变量后内置名失效 | 脚本自身的绑定优先于中文名 | 避免用内置名作变量名 |

## 七、相关章节

语言语法、对象与运算见「代码」；简写方言见「mpe 简写」；全部中英文名字、签名与用途见「API 对照」。
`,
